import{_ as t,c as a,o as i,al as l}from"./chunks/framework.CT7RwC5a.js";const c=JSON.parse('{"title":"uORB Message Reference","description":"","frontmatter":{},"headers":[],"relativePath":"en/msg_docs/index.md","filePath":"en/msg_docs/index.md"}'),o={name:"en/msg_docs/index.md"};function r(s,e,n,h,m,u){return i(),a("div",null,e[0]||(e[0]=[l('<h1 id="uorb-message-reference" tabindex="-1">uORB Message Reference <a class="header-anchor" href="#uorb-message-reference" aria-label="Permalink to &quot;uORB Message Reference&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This list is <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/msg/generate_msg_docs.py" target="_blank" rel="noreferrer">auto-generated</a> from the source code.</p></div><p>This topic lists the UORB messages available in PX4 (some of which may be may be shared by the <a href="./../ros/ros2_comm.html">PX4-ROS 2 Bridge</a>).</p><p><a href="./../middleware/uorb.html#message-versioning">Versioned messages</a> track changes to their definitions, with each modification resulting in a version increment. These messages are most likely shared through the PX4-ROS 2 Bridge.</p><p>Graphs showing how these are used <a href="./../middleware/uorb_graph.html">can be found here</a>.</p><h2 id="versioned-messages" tabindex="-1">Versioned Messages <a class="header-anchor" href="#versioned-messages" aria-label="Permalink to &quot;Versioned Messages&quot;">​</a></h2><ul><li><a href="./ActuatorMotors.html">ActuatorMotors</a> — Motor control message</li><li><a href="./ActuatorServos.html">ActuatorServos</a> — Servo control message</li><li><a href="./AirspeedValidated.html">AirspeedValidated</a></li><li><a href="./ArmingCheckReply.html">ArmingCheckReply</a> — Arming check reply.</li><li><a href="./ArmingCheckRequest.html">ArmingCheckRequest</a> — Arming check request.</li><li><a href="./BatteryStatus.html">BatteryStatus</a> — Battery status</li><li><a href="./ConfigOverrides.html">ConfigOverrides</a> — Configurable overrides by (external) modes or mode executors</li><li><a href="./Event.html">Event</a> — Events interface</li><li><a href="./FixedWingLateralSetpoint.html">FixedWingLateralSetpoint</a> — Fixed Wing Lateral Setpoint message Used by the fw_lateral_longitudinal_control module At least one of course, airspeed_direction, or lateral_acceleration must be finite.</li><li><a href="./FixedWingLongitudinalSetpoint.html">FixedWingLongitudinalSetpoint</a> — Fixed Wing Longitudinal Setpoint message Used by the fw_lateral_longitudinal_control module If pitch_direct and throttle_direct are not both finite, then the controller relies on altitude/height_rate and equivalent_airspeed to control vertical motion. If both altitude and height_rate are NAN, the controller maintains the current altitude.</li><li><a href="./GotoSetpoint.html">GotoSetpoint</a> — Position and (optional) heading setpoints with corresponding speed constraints Setpoints are intended as inputs to position and heading smoothers, respectively Setpoints do not need to be kinematically consistent Optional heading setpoints may be specified as controlled by the respective flag Unset optional setpoints are not controlled Unset optional constraints default to vehicle specifications</li><li><a href="./HomePosition.html">HomePosition</a> — GPS home position in WGS84 coordinates.</li><li><a href="./LateralControlConfiguration.html">LateralControlConfiguration</a> — Fixed Wing Lateral Control Configuration message Used by the fw_lateral_longitudinal_control module to constrain FixedWingLateralSetpoint messages.</li><li><a href="./LongitudinalControlConfiguration.html">LongitudinalControlConfiguration</a> — Fixed Wing Longitudinal Control Configuration message Used by the fw_lateral_longitudinal_control module and TECS to constrain FixedWingLongitudinalSetpoint messages and configure the resultant setpoints.</li><li><a href="./ManualControlSetpoint.html">ManualControlSetpoint</a></li><li><a href="./ModeCompleted.html">ModeCompleted</a> — Mode completion result, published by an active mode. The possible values of nav_state are defined in the VehicleStatus msg. Note that this is not always published (e.g. when a user switches modes or on failsafe activation)</li><li><a href="./RegisterExtComponentReply.html">RegisterExtComponentReply</a></li><li><a href="./RegisterExtComponentRequest.html">RegisterExtComponentRequest</a> — Request to register an external component</li><li><a href="./TrajectorySetpoint.html">TrajectorySetpoint</a> — Trajectory setpoint in NED frame Input to PID position controller. Needs to be kinematically consistent and feasible for smooth flight. setting a value to NaN means the state should not be controlled</li><li><a href="./UnregisterExtComponent.html">UnregisterExtComponent</a></li><li><a href="./VehicleAngularVelocity.html">VehicleAngularVelocity</a></li><li><a href="./VehicleAttitude.html">VehicleAttitude</a> — This is similar to the mavlink message ATTITUDE_QUATERNION, but for onboard use The quaternion uses the Hamilton convention, and the order is q(w, x, y, z)</li><li><a href="./VehicleAttitudeSetpoint.html">VehicleAttitudeSetpoint</a></li><li><a href="./VehicleCommand.html">VehicleCommand</a> — Vehicle Command uORB message. Used for commanding a mission / action / etc. Follows the MAVLink COMMAND_INT / COMMAND_LONG definition</li><li><a href="./VehicleCommandAck.html">VehicleCommandAck</a> — Vehicle Command Ackonwledgement uORB message. Used for acknowledging the vehicle command being received. Follows the MAVLink COMMAND_ACK message definition</li><li><a href="./VehicleControlMode.html">VehicleControlMode</a></li><li><a href="./VehicleGlobalPosition.html">VehicleGlobalPosition</a> — Fused global position in WGS84. This struct contains global position estimation. It is not the raw GPS measurement (@see vehicle_gps_position). This topic is usually published by the position estimator, which will take more sources of information into account than just GPS, e.g. control inputs of the vehicle in a Kalman-filter implementation.</li><li><a href="./VehicleLandDetected.html">VehicleLandDetected</a></li><li><a href="./VehicleLocalPosition.html">VehicleLocalPosition</a> — Fused local position in NED. The coordinate system origin is the vehicle position at the time when the EKF2-module was started.</li><li><a href="./VehicleOdometry.html">VehicleOdometry</a> — Vehicle odometry data. Fits ROS REP 147 for aerial vehicles</li><li><a href="./VehicleRatesSetpoint.html">VehicleRatesSetpoint</a></li><li><a href="./VehicleStatus.html">VehicleStatus</a> — Encodes the system state of the vehicle published by commander</li><li><a href="./VtolVehicleStatus.html">VtolVehicleStatus</a> — VEHICLE_VTOL_STATE, should match 1:1 MAVLinks&#39;s MAV_VTOL_STATE</li><li><a href="./Wind.html">Wind</a> — Wind estimate (from EKF2)</li></ul><h2 id="unversioned-messages" tabindex="-1">Unversioned Messages <a class="header-anchor" href="#unversioned-messages" aria-label="Permalink to &quot;Unversioned Messages&quot;">​</a></h2><ul><li><a href="./ActionRequest.html">ActionRequest</a> — Action request for the vehicle&#39;s main state</li><li><a href="./ActuatorArmed.html">ActuatorArmed</a></li><li><a href="./ActuatorControlsStatus.html">ActuatorControlsStatus</a></li><li><a href="./ActuatorOutputs.html">ActuatorOutputs</a></li><li><a href="./ActuatorServosTrim.html">ActuatorServosTrim</a> — Servo trims, added as offset to servo outputs</li><li><a href="./ActuatorTest.html">ActuatorTest</a></li><li><a href="./AdcReport.html">AdcReport</a></li><li><a href="./Airspeed.html">Airspeed</a> — Airspeed data from sensors</li><li><a href="./AirspeedWind.html">AirspeedWind</a> — Wind estimate (from airspeed_selector)</li><li><a href="./AutotuneAttitudeControlStatus.html">AutotuneAttitudeControlStatus</a></li><li><a href="./BatteryInfo.html">BatteryInfo</a> — Battery information</li><li><a href="./ButtonEvent.html">ButtonEvent</a></li><li><a href="./CameraCapture.html">CameraCapture</a></li><li><a href="./CameraStatus.html">CameraStatus</a></li><li><a href="./CameraTrigger.html">CameraTrigger</a></li><li><a href="./CanInterfaceStatus.html">CanInterfaceStatus</a></li><li><a href="./CellularStatus.html">CellularStatus</a> — Cellular status</li><li><a href="./CollisionConstraints.html">CollisionConstraints</a> — Local setpoint constraints in NED frame setting something to NaN means that no limit is provided</li><li><a href="./ControlAllocatorStatus.html">ControlAllocatorStatus</a></li><li><a href="./Cpuload.html">Cpuload</a></li><li><a href="./DatamanRequest.html">DatamanRequest</a></li><li><a href="./DatamanResponse.html">DatamanResponse</a></li><li><a href="./DebugArray.html">DebugArray</a></li><li><a href="./DebugKeyValue.html">DebugKeyValue</a></li><li><a href="./DebugValue.html">DebugValue</a></li><li><a href="./DebugVect.html">DebugVect</a></li><li><a href="./DifferentialPressure.html">DifferentialPressure</a></li><li><a href="./DistanceSensor.html">DistanceSensor</a> — DISTANCE_SENSOR message data</li><li><a href="./DistanceSensorModeChangeRequest.html">DistanceSensorModeChangeRequest</a></li><li><a href="./DronecanNodeStatus.html">DronecanNodeStatus</a></li><li><a href="./Ekf2Timestamps.html">Ekf2Timestamps</a> — this message contains the (relative) timestamps of the sensor inputs used by EKF2. It can be used for reproducible replay.</li><li><a href="./EscReport.html">EscReport</a></li><li><a href="./EscStatus.html">EscStatus</a></li><li><a href="./EstimatorAidSource1d.html">EstimatorAidSource1d</a></li><li><a href="./EstimatorAidSource2d.html">EstimatorAidSource2d</a></li><li><a href="./EstimatorAidSource3d.html">EstimatorAidSource3d</a></li><li><a href="./EstimatorBias.html">EstimatorBias</a></li><li><a href="./EstimatorBias3d.html">EstimatorBias3d</a></li><li><a href="./EstimatorEventFlags.html">EstimatorEventFlags</a></li><li><a href="./EstimatorGpsStatus.html">EstimatorGpsStatus</a></li><li><a href="./EstimatorInnovations.html">EstimatorInnovations</a></li><li><a href="./EstimatorSelectorStatus.html">EstimatorSelectorStatus</a></li><li><a href="./EstimatorSensorBias.html">EstimatorSensorBias</a> — Sensor readings and in-run biases in SI-unit form. Sensor readings are compensated for static offsets, scale errors, in-run bias and thermal drift (if thermal compensation is enabled and available).</li><li><a href="./EstimatorStates.html">EstimatorStates</a></li><li><a href="./EstimatorStatus.html">EstimatorStatus</a></li><li><a href="./EstimatorStatusFlags.html">EstimatorStatusFlags</a></li><li><a href="./FailsafeFlags.html">FailsafeFlags</a> — Input flags for the failsafe state machine set by the arming &amp; health checks.</li><li><a href="./FailureDetectorStatus.html">FailureDetectorStatus</a></li><li><a href="./FigureEightStatus.html">FigureEightStatus</a></li><li><a href="./FixedWingLateralGuidanceStatus.html">FixedWingLateralGuidanceStatus</a> — Fixed Wing Lateral Guidance Status message Published by fw_pos_control module to report the resultant lateral setpoints and NPFG debug outputs</li><li><a href="./FixedWingLateralStatus.html">FixedWingLateralStatus</a> — Fixed Wing Lateral Status message Published by the fw_lateral_longitudinal_control module to report the resultant lateral setpoint</li><li><a href="./FixedWingRunwayControl.html">FixedWingRunwayControl</a> — Auxiliary control fields for fixed-wing runway takeoff/landing</li><li><a href="./FlightPhaseEstimation.html">FlightPhaseEstimation</a></li><li><a href="./FollowTarget.html">FollowTarget</a></li><li><a href="./FollowTargetEstimator.html">FollowTargetEstimator</a></li><li><a href="./FollowTargetStatus.html">FollowTargetStatus</a></li><li><a href="./FuelTankStatus.html">FuelTankStatus</a></li><li><a href="./GeneratorStatus.html">GeneratorStatus</a></li><li><a href="./GeofenceResult.html">GeofenceResult</a></li><li><a href="./GeofenceStatus.html">GeofenceStatus</a></li><li><a href="./GimbalControls.html">GimbalControls</a></li><li><a href="./GimbalDeviceAttitudeStatus.html">GimbalDeviceAttitudeStatus</a></li><li><a href="./GimbalDeviceInformation.html">GimbalDeviceInformation</a></li><li><a href="./GimbalDeviceSetAttitude.html">GimbalDeviceSetAttitude</a></li><li><a href="./GimbalManagerInformation.html">GimbalManagerInformation</a></li><li><a href="./GimbalManagerSetAttitude.html">GimbalManagerSetAttitude</a></li><li><a href="./GimbalManagerSetManualControl.html">GimbalManagerSetManualControl</a></li><li><a href="./GimbalManagerStatus.html">GimbalManagerStatus</a></li><li><a href="./GpioConfig.html">GpioConfig</a> — GPIO configuration</li><li><a href="./GpioIn.html">GpioIn</a> — GPIO mask and state</li><li><a href="./GpioOut.html">GpioOut</a> — GPIO mask and state</li><li><a href="./GpioRequest.html">GpioRequest</a> — Request GPIO mask to be read</li><li><a href="./GpsDump.html">GpsDump</a> — This message is used to dump the raw gps communication to the log.</li><li><a href="./GpsInjectData.html">GpsInjectData</a></li><li><a href="./Gripper.html">Gripper</a> — # Used to command an actuation in the gripper, which is mapped to a specific output in the control allocation module</li><li><a href="./HealthReport.html">HealthReport</a></li><li><a href="./HeaterStatus.html">HeaterStatus</a></li><li><a href="./HoverThrustEstimate.html">HoverThrustEstimate</a></li><li><a href="./InputRc.html">InputRc</a></li><li><a href="./InternalCombustionEngineControl.html">InternalCombustionEngineControl</a></li><li><a href="./InternalCombustionEngineStatus.html">InternalCombustionEngineStatus</a></li><li><a href="./IridiumsbdStatus.html">IridiumsbdStatus</a></li><li><a href="./IrlockReport.html">IrlockReport</a> — IRLOCK_REPORT message data</li><li><a href="./LandingGear.html">LandingGear</a></li><li><a href="./LandingGearWheel.html">LandingGearWheel</a></li><li><a href="./LandingTargetInnovations.html">LandingTargetInnovations</a></li><li><a href="./LandingTargetPose.html">LandingTargetPose</a> — Relative position of precision land target in navigation (body fixed, north aligned, NED) and inertial (world fixed, north aligned, NED) frames</li><li><a href="./LaunchDetectionStatus.html">LaunchDetectionStatus</a> — Status of the launch detection state machine (fixed-wing only)</li><li><a href="./LedControl.html">LedControl</a> — LED control: control a single or multiple LED&#39;s. These are the externally visible LED&#39;s, not the board LED&#39;s</li><li><a href="./LogMessage.html">LogMessage</a> — A logging message, output with PX4_WARN, PX4_ERR, PX4_INFO</li><li><a href="./LoggerStatus.html">LoggerStatus</a></li><li><a href="./MagWorkerData.html">MagWorkerData</a></li><li><a href="./MagnetometerBiasEstimate.html">MagnetometerBiasEstimate</a></li><li><a href="./ManualControlSwitches.html">ManualControlSwitches</a></li><li><a href="./MavlinkLog.html">MavlinkLog</a></li><li><a href="./MavlinkTunnel.html">MavlinkTunnel</a> — MAV_TUNNEL_PAYLOAD_TYPE enum</li><li><a href="./MessageFormatRequest.html">MessageFormatRequest</a></li><li><a href="./MessageFormatResponse.html">MessageFormatResponse</a></li><li><a href="./Mission.html">Mission</a></li><li><a href="./MissionResult.html">MissionResult</a></li><li><a href="./MountOrientation.html">MountOrientation</a></li><li><a href="./NavigatorMissionItem.html">NavigatorMissionItem</a></li><li><a href="./NavigatorStatus.html">NavigatorStatus</a> — Current status of a Navigator mode The possible values of nav_state are defined in the VehicleStatus msg.</li><li><a href="./NeuralControl.html">NeuralControl</a> — Neural control</li><li><a href="./NormalizedUnsignedSetpoint.html">NormalizedUnsignedSetpoint</a></li><li><a href="./ObstacleDistance.html">ObstacleDistance</a> — Obstacle distances in front of the sensor.</li><li><a href="./OffboardControlMode.html">OffboardControlMode</a> — Off-board control mode</li><li><a href="./OnboardComputerStatus.html">OnboardComputerStatus</a> — ONBOARD_COMPUTER_STATUS message data</li><li><a href="./OpenDroneIdArmStatus.html">OpenDroneIdArmStatus</a></li><li><a href="./OpenDroneIdOperatorId.html">OpenDroneIdOperatorId</a></li><li><a href="./OpenDroneIdSelfId.html">OpenDroneIdSelfId</a></li><li><a href="./OpenDroneIdSystem.html">OpenDroneIdSystem</a></li><li><a href="./OrbTest.html">OrbTest</a></li><li><a href="./OrbTestLarge.html">OrbTestLarge</a></li><li><a href="./OrbTestMedium.html">OrbTestMedium</a></li><li><a href="./OrbitStatus.html">OrbitStatus</a> — ORBIT_YAW_BEHAVIOUR</li><li><a href="./ParameterResetRequest.html">ParameterResetRequest</a> — ParameterResetRequest : Used by the primary to reset one or all parameter value(s) on the remote</li><li><a href="./ParameterSetUsedRequest.html">ParameterSetUsedRequest</a> — ParameterSetUsedRequest : Used by a remote to update the used flag for a parameter on the primary</li><li><a href="./ParameterSetValueRequest.html">ParameterSetValueRequest</a> — ParameterSetValueRequest : Used by a remote or primary to update the value for a parameter at the other end</li><li><a href="./ParameterSetValueResponse.html">ParameterSetValueResponse</a> — ParameterSetValueResponse : Response to a set value request by either primary or secondary</li><li><a href="./ParameterUpdate.html">ParameterUpdate</a> — This message is used to notify the system about one or more parameter changes</li><li><a href="./Ping.html">Ping</a></li><li><a href="./PositionControllerLandingStatus.html">PositionControllerLandingStatus</a></li><li><a href="./PositionControllerStatus.html">PositionControllerStatus</a></li><li><a href="./PositionSetpoint.html">PositionSetpoint</a> — this file is only used in the position_setpoint triple as a dependency</li><li><a href="./PositionSetpointTriplet.html">PositionSetpointTriplet</a> — Global position setpoint triplet in WGS84 coordinates. This are the three next waypoints (or just the next two or one).</li><li><a href="./PowerButtonState.html">PowerButtonState</a> — power button state notification message</li><li><a href="./PowerMonitor.html">PowerMonitor</a> — power monitor message</li><li><a href="./PpsCapture.html">PpsCapture</a></li><li><a href="./PurePursuitStatus.html">PurePursuitStatus</a> — Pure pursuit status</li><li><a href="./PwmInput.html">PwmInput</a></li><li><a href="./Px4ioStatus.html">Px4ioStatus</a></li><li><a href="./QshellReq.html">QshellReq</a></li><li><a href="./QshellRetval.html">QshellRetval</a></li><li><a href="./RadioStatus.html">RadioStatus</a></li><li><a href="./RateCtrlStatus.html">RateCtrlStatus</a></li><li><a href="./RcChannels.html">RcChannels</a></li><li><a href="./RcParameterMap.html">RcParameterMap</a></li><li><a href="./RoverAttitudeSetpoint.html">RoverAttitudeSetpoint</a> — Rover Attitude Setpoint</li><li><a href="./RoverAttitudeStatus.html">RoverAttitudeStatus</a> — Rover Attitude Status</li><li><a href="./RoverPositionSetpoint.html">RoverPositionSetpoint</a> — Rover Position Setpoint</li><li><a href="./RoverRateSetpoint.html">RoverRateSetpoint</a> — Rover Rate setpoint</li><li><a href="./RoverRateStatus.html">RoverRateStatus</a> — Rover Rate Status</li><li><a href="./RoverSteeringSetpoint.html">RoverSteeringSetpoint</a> — Rover Steering setpoint</li><li><a href="./RoverThrottleSetpoint.html">RoverThrottleSetpoint</a> — Rover Throttle setpoint</li><li><a href="./RoverVelocitySetpoint.html">RoverVelocitySetpoint</a> — Rover Velocity Setpoint</li><li><a href="./RoverVelocityStatus.html">RoverVelocityStatus</a> — Rover Velocity Status</li><li><a href="./Rpm.html">Rpm</a></li><li><a href="./RtlStatus.html">RtlStatus</a></li><li><a href="./RtlTimeEstimate.html">RtlTimeEstimate</a></li><li><a href="./SatelliteInfo.html">SatelliteInfo</a></li><li><a href="./SensorAccel.html">SensorAccel</a></li><li><a href="./SensorAccelFifo.html">SensorAccelFifo</a></li><li><a href="./SensorAirflow.html">SensorAirflow</a></li><li><a href="./SensorBaro.html">SensorBaro</a></li><li><a href="./SensorCombined.html">SensorCombined</a> — Sensor readings in SI-unit form. These fields are scaled and offset-compensated where possible and do not change with board revisions and sensor updates.</li><li><a href="./SensorCorrection.html">SensorCorrection</a> — Sensor corrections in SI-unit form for the voted sensor</li><li><a href="./SensorGnssRelative.html">SensorGnssRelative</a> — GNSS relative positioning information in NED frame. The NED frame is defined as the local topological system at the reference station.</li><li><a href="./SensorGps.html">SensorGps</a> — GPS position in WGS84 coordinates. the field &#39;timestamp&#39; is for the position &amp; velocity (microseconds)</li><li><a href="./SensorGyro.html">SensorGyro</a></li><li><a href="./SensorGyroFft.html">SensorGyroFft</a></li><li><a href="./SensorGyroFifo.html">SensorGyroFifo</a></li><li><a href="./SensorHygrometer.html">SensorHygrometer</a></li><li><a href="./SensorMag.html">SensorMag</a></li><li><a href="./SensorOpticalFlow.html">SensorOpticalFlow</a></li><li><a href="./SensorPreflightMag.html">SensorPreflightMag</a> — Pre-flight sensor check metrics. The topic will not be updated when the vehicle is armed</li><li><a href="./SensorSelection.html">SensorSelection</a> — Sensor ID&#39;s for the voted sensors output on the sensor_combined topic. Will be updated on startup of the sensor module and when sensor selection changes</li><li><a href="./SensorUwb.html">SensorUwb</a> — UWB distance contains the distance information measured by an ultra-wideband positioning system, such as Pozyx or NXP Rddrone.</li><li><a href="./SensorsStatus.html">SensorsStatus</a> — Sensor check metrics. This will be zero for a sensor that&#39;s primary or unpopulated.</li><li><a href="./SensorsStatusImu.html">SensorsStatusImu</a> — Sensor check metrics. This will be zero for a sensor that&#39;s primary or unpopulated.</li><li><a href="./SystemPower.html">SystemPower</a></li><li><a href="./TakeoffStatus.html">TakeoffStatus</a> — Status of the takeoff state machine currently just available for multicopters</li><li><a href="./TaskStackInfo.html">TaskStackInfo</a> — stack information for a single running process</li><li><a href="./TecsStatus.html">TecsStatus</a></li><li><a href="./TelemetryStatus.html">TelemetryStatus</a></li><li><a href="./TiltrotorExtraControls.html">TiltrotorExtraControls</a></li><li><a href="./TimesyncStatus.html">TimesyncStatus</a></li><li><a href="./TrajectorySetpoint6dof.html">TrajectorySetpoint6dof</a> — Trajectory setpoint in NED frame Input to position controller.</li><li><a href="./TransponderReport.html">TransponderReport</a></li><li><a href="./TuneControl.html">TuneControl</a> — This message is used to control the tunes, when the tune_id is set to CUSTOM then the frequency, duration are used otherwise those values are ignored.</li><li><a href="./UavcanParameterRequest.html">UavcanParameterRequest</a> — UAVCAN-MAVLink parameter bridge request type</li><li><a href="./UavcanParameterValue.html">UavcanParameterValue</a> — UAVCAN-MAVLink parameter bridge response type</li><li><a href="./UlogStream.html">UlogStream</a> — Message to stream ULog data from the logger. Corresponds to the LOGGING_DATA mavlink message</li><li><a href="./UlogStreamAck.html">UlogStreamAck</a> — Ack a previously sent ulog_stream message that had the NEED_ACK flag set</li><li><a href="./VehicleAcceleration.html">VehicleAcceleration</a></li><li><a href="./VehicleAirData.html">VehicleAirData</a></li><li><a href="./VehicleAngularAccelerationSetpoint.html">VehicleAngularAccelerationSetpoint</a></li><li><a href="./VehicleConstraints.html">VehicleConstraints</a> — Local setpoint constraints in NED frame setting something to NaN means that no limit is provided</li><li><a href="./VehicleImu.html">VehicleImu</a> — IMU readings in SI-unit form.</li><li><a href="./VehicleImuStatus.html">VehicleImuStatus</a></li><li><a href="./VehicleLocalPositionSetpoint.html">VehicleLocalPositionSetpoint</a> — Local position setpoint in NED frame Telemetry of PID position controller to monitor tracking. NaN means the state was not controlled</li><li><a href="./VehicleMagnetometer.html">VehicleMagnetometer</a></li><li><a href="./VehicleOpticalFlow.html">VehicleOpticalFlow</a> — Optical flow in XYZ body frame in SI units.</li><li><a href="./VehicleOpticalFlowVel.html">VehicleOpticalFlowVel</a></li><li><a href="./VehicleRoi.html">VehicleRoi</a> — Vehicle Region Of Interest (ROI)</li><li><a href="./VehicleThrustSetpoint.html">VehicleThrustSetpoint</a></li><li><a href="./VehicleTorqueSetpoint.html">VehicleTorqueSetpoint</a></li><li><a href="./VelocityLimits.html">VelocityLimits</a> — Velocity and yaw rate limits for a multicopter position slow mode only</li><li><a href="./WheelEncoders.html">WheelEncoders</a></li><li><a href="./YawEstimatorStatus.html">YawEstimatorStatus</a></li><li><a href="./AirspeedValidatedV0.html">AirspeedValidatedV0</a></li><li><a href="./ArmingCheckReplyV0.html">ArmingCheckReplyV0</a></li><li><a href="./BatteryStatusV0.html">BatteryStatusV0</a> — Battery status</li><li><a href="./EventV0.html">EventV0</a> — this message is required here in the msg_old folder because other msg are depending on it Events interface</li><li><a href="./HomePositionV0.html">HomePositionV0</a> — GPS home position in WGS84 coordinates.</li><li><a href="./VehicleAttitudeSetpointV0.html">VehicleAttitudeSetpointV0</a></li><li><a href="./VehicleLocalPositionV0.html">VehicleLocalPositionV0</a> — Fused local position in NED. The coordinate system origin is the vehicle position at the time when the EKF2-module was started.</li><li><a href="./VehicleStatusV0.html">VehicleStatusV0</a> — Encodes the system state of the vehicle published by commander</li></ul>',9)]))}const d=t(o,[["render",r]]);export{c as __pageData,d as default};
